const char *speciesName(int id, Lang lang) {
  if (id < 0 || id > kMaxSpecies) return "?";
  return lang == Lang::De ? species_de[id] : species_en[id];
}
int speciesType(int id, int which) {
  if (id < 0 || id > kMaxSpecies || which < 0 || which > 1) return -1;
  int t = species_types[id][which];
  return t == 255 ? -1 : t;
}
int speciesFamily(int id) { return (id < 0 || id > kMaxSpecies) ? 0 : species_family[id]; }
const char *typeName(int t, Lang lang) {
  if (t < 0 || t >= 18) return "";
  return lang == Lang::De ? type_de[t] : type_en[t];
}
const char *locationName(int gen, int id, Lang lang) {
  const LocName *tab = gen >= 7 ? loc7 : loc6;
  int lo = 0, hi = (gen >= 7 ? loc7_count : loc6_count) - 1;
  while (lo <= hi) {
    int mid = (lo + hi) / 2;
    if (tab[mid].id == id) return lang == Lang::De ? tab[mid].de : tab[mid].en;
    if (tab[mid].id < id) lo = mid + 1; else hi = mid - 1;
  }
  return nullptr;
}
